<script setup lang="ts">
import {computed,ref} from 'vue'
import type {GraphNode,GraphEdge,KnowledgePoint} from '@/api/types'
const props=defineProps<{nodes:GraphNode[];edges:GraphEdge[];points:KnowledgePoint[]}>()
const emit=defineEmits<{select:[id:string]}>()
const query=ref(''),selected=ref(''),zoom=ref(1)
const pointMap=computed(()=>new Map(props.points.map(p=>[p.ID,p])))
const groups=['数据结构','计算机组成原理','操作系统','计算机网络','资料概念']
const positions=computed(()=>{const seen=new Map<string,number>(),result=new Map<string,{x:number;y:number;group:number}>();for(const n of props.nodes){const group=groups.indexOf(pointMap.value.get(n.KnowledgePointID)?.SubjectName||'资料概念'),row=seen.get(String(group))||0;seen.set(String(group),row+1);result.set(n.ID,{x:55+group*265,y:85+row*78,group})}return result})
const height=computed(()=>Math.max(400,...Array.from(positions.value.values()).map(p=>p.y+70)))
const visible=computed(()=>props.nodes.filter(n=>!query.value||`${n.Name} ${n.Description}`.includes(query.value)).slice(0,600))
const ids=computed(()=>new Set(visible.value.map(n=>n.ID)))
const links=computed(()=>props.edges.filter(e=>ids.value.has(e.FromEntityID)&&ids.value.has(e.ToEntityID)))
const neighbors=computed(()=>{const s=new Set([selected.value]);for(const e of props.edges){if(e.FromEntityID===selected.value)s.add(e.ToEntityID);if(e.ToEntityID===selected.value)s.add(e.FromEntityID)}return s})
function select(id:string){selected.value=selected.value===id?'':id;emit('select',selected.value)}
</script>
<template><section class="card section"><h2>知识关系图</h2><div class="toolbar-actions"><input v-model="query" aria-label="查找图谱节点" placeholder="查找知识点或资料概念"/><label>缩放 <input v-model.number="zoom" type="range" min="0.6" max="2" step="0.1"/></label><button class="secondary" @click="query='';selected='';zoom=1;emit('select','')">重置视图</button></div><p class="reason">点击节点高亮相邻关系，并查看下方的来源证据。显示 {{visible.length}} / {{nodes.length}} 个节点；单次最多绘制600个，可输入名称定位。</p><div style="overflow:auto;max-height:640px;border:1px solid #dbe2ec;border-radius:10px"><svg :width="1340*zoom" :height="height*zoom" :viewBox="`0 0 1340 ${height}`" role="img" aria-label="408知识图谱节点和关系"><defs><marker id="graph-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#64748b"/></marker></defs><text v-for="(g,i) in groups" :key="g" :x="28+i*265" y="30" fill="#475569" font-size="17" font-weight="bold">{{g}}</text><line v-for="e in links" :key="e.ID" :x1="positions.get(e.FromEntityID)?.x" :y1="positions.get(e.FromEntityID)?.y" :x2="positions.get(e.ToEntityID)?.x" :y2="positions.get(e.ToEntityID)?.y" :stroke="selected&&(e.FromEntityID===selected||e.ToEntityID===selected)?'#2563eb':'#94a3b8'" :stroke-width="selected&&(e.FromEntityID===selected||e.ToEntityID===selected)?3:1.2" :opacity="!selected||e.FromEntityID===selected||e.ToEntityID===selected?0.7:0.1" marker-end="url(#graph-arrow)"><title>{{e.RelationType}}</title></line><g v-for="n in visible" :key="n.ID" :transform="`translate(${positions.get(n.ID)?.x},${positions.get(n.ID)?.y})`" :opacity="!selected||neighbors.has(n.ID)?1:0.25" role="button" tabindex="0" :aria-label="n.Name" @click="select(n.ID)" @keydown.enter="select(n.ID)" @keydown.space.prevent="select(n.ID)" style="cursor:pointer"><title>{{n.Name}}</title><circle :r="selected===n.ID?12:8" :fill="n.Source==='canonical'?'#2563eb':'#9333ea'"/><text x="16" y="5" font-size="13" fill="#1e293b">{{n.Name.length>15?n.Name.slice(0,15)+'…':n.Name}}</text></g></svg></div></section></template>
